import{_ as a,o as s,c as i,a5 as t}from"./chunks/framework.a5no_H3L.js";const k=JSON.parse('{"title":"类型恢复与结构体识别","description":"反编译产物里，类型信息大量缺失——机器码里没有「这是结构体、那是数组、这个变量是 int」这些标注。反编译器只能把未知数据标成 unk、void*。这一章讲如何从反汇编里把类型和结构体恢复回来，让伪代码从「一坨指针」变成「可读的 C 代码」。","frontmatter":{"type":"explanation","level":"advanced"},"headers":[],"relativePath":"reverse-engineering/05-static-analysis/chapter-02-type-recovery.md","filePath":"reverse-engineering/05-static-analysis/chapter-02-type-recovery.md"}'),r={name:"reverse-engineering/05-static-analysis/chapter-02-type-recovery.md"};function n(l,e,c,d,p,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="类型恢复与结构体识别" tabindex="-1" data-src-line="2" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">类型恢复与结构体识别 <a class="header-anchor" href="#类型恢复与结构体识别" aria-label="Permalink to &quot;类型恢复与结构体识别&quot;">​</a></h1><p data-src-line="4" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">反编译产物里，类型信息大量缺失——机器码里没有「这是结构体、那是数组、这个变量是 int」这些标注。反编译器只能把未知数据标成 <code>unk</code>、<code>void*</code>。这一章讲如何从反汇编里<strong>把类型和结构体恢复回来</strong>，让伪代码从「一坨指针」变成「可读的 C 代码」。</p><h2 id="_1-为什么需要类型恢复" tabindex="-1" data-src-line="6" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">1. 为什么需要类型恢复 <a class="header-anchor" href="#_1-为什么需要类型恢复" aria-label="Permalink to &quot;1. 为什么需要类型恢复&quot;">​</a></h2><p data-src-line="8" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">编译时，类型信息大多被丢掉：<code>int</code>、<code>char*</code>、<code>struct Point</code> 在机器码里都只是一段内存和一套操作。反编译器面对一段内存，只知道「这里被读写了 4 字节」，不知道它是什么。</p><p data-src-line="10" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">类型恢复的目标，是<strong>通过观察「这段内存怎么被使用」，反推它是什么类型</strong>。使用方式会留下线索：读写宽度、访问偏移、参与什么运算、传给什么函数。</p><h2 id="_2-从访问偏移恢复结构体" tabindex="-1" data-src-line="12" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">2. 从访问偏移恢复结构体 <a class="header-anchor" href="#_2-从访问偏移恢复结构体" aria-label="Permalink to &quot;2. 从访问偏移恢复结构体&quot;">​</a></h2><p data-src-line="14" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">结构体的成员，编译后是「基址 + 固定偏移」的访问。观察这些偏移，就能拼出结构体布局：</p><div class="language-asm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">asm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">mov</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rcx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],   </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">eax</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    ; 偏移 0，4 字节</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">mov</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rcx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">edx</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    ; 偏移 4，4 字节</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">mov</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rcx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">r8d</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">    ; 偏移 8，4 字节</span></span></code></pre></div><p data-src-line="22" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">这段代码往 <code>rcx</code> 指向的内存写了三个 4 字节，偏移分别是 0、4、8。结合上下文，可以推断 <code>rcx</code> 指向一个含三个 <code>int</code> 字段的结构体，反推成：</p><div class="language-c vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">struct</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> a; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> b; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">int</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> c; };</span></span></code></pre></div><p data-src-line="28" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md"><strong>方法</strong>：收集所有「基址 + 偏移」的访问，按偏移分组，同一偏移、同宽度的访问对应同一个成员。偏移 0 是第一个成员，偏移 4 是第二个，以此类推。</p><h2 id="_3-从索引缩放恢复数组" tabindex="-1" data-src-line="30" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">3. 从索引缩放恢复数组 <a class="header-anchor" href="#_3-从索引缩放恢复数组" aria-label="Permalink to &quot;3. 从索引缩放恢复数组&quot;">​</a></h2><p data-src-line="32" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">数组访问的特征是「基址 + 索引 × 元素大小」：</p><div class="language-asm vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">asm</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">mov</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  eax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rdx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">; 元素 4 字节</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">mov</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  ecx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, [</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rdx</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">+</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">rax</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">*</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]   </span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">; 元素 8 字节</span></span></code></pre></div><p data-src-line="39" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md"><code>×4</code> 说明是 4 字节元素（<code>int</code>、<code>float</code>、指针），<code>×8</code> 是 8 字节元素（<code>long</code>、<code>double</code>、指针）。结合「谁在当索引、循环怎么走」，能还原出数组的类型和维度。</p><h2 id="_4-从调用约定恢复参数" tabindex="-1" data-src-line="41" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">4. 从调用约定恢复参数 <a class="header-anchor" href="#_4-从调用约定恢复参数" aria-label="Permalink to &quot;4. 从调用约定恢复参数&quot;">​</a></h2><p data-src-line="43" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">函数的参数个数和类型，也能从调用处反推：</p><ul data-src-line="45" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md"><li data-src-line="45" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md"><strong>参数个数</strong>：x64 下，前 4 个参数走 <code>RCX/RDX/R8/R9</code>，看调用前设置了哪几个寄存器，就知道传了几个参数。</li><li data-src-line="46" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md"><strong>参数类型</strong>：看参数被怎么用——作为指针解引用、作为整数比较、还是传给别的函数。</li><li data-src-line="47" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md"><strong>返回值</strong>：看 <code>RAX</code> 返回后被怎么用。</li></ul><p data-src-line="49" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">例如，一段代码 <code>lea rcx, [str]; call foo</code>，说明 <code>foo</code> 的第一个参数是个指针（<code>rcx</code> 里放的是地址）。</p><h2 id="_5-控制流与数据流分析" tabindex="-1" data-src-line="51" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">5. 控制流与数据流分析 <a class="header-anchor" href="#_5-控制流与数据流分析" aria-label="Permalink to &quot;5. 控制流与数据流分析&quot;">​</a></h2><p data-src-line="53" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">类型恢复依赖两条分析线：</p><ul data-src-line="55" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md"><li data-src-line="55" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md"><strong>控制流分析</strong>：理解程序的分支、循环结构，这是识别「这段代码在做什么」的基础。</li><li data-src-line="56" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md"><strong>数据流分析</strong>：追踪一个值从哪来、到哪去、被怎么变换。追踪一个「从 <code>malloc</code> 返回、被写入若干字段、再传给某函数」的值，就能还原出它的结构。</li></ul><p data-src-line="58" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">反汇编器和反编译器会做一部分自动分析，但关键的「这是什么类型」仍需要人工判断。这正是逆向的价值所在。</p><h2 id="_6-工具操作-定义结构体" tabindex="-1" data-src-line="60" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">6. 工具操作：定义结构体 <a class="header-anchor" href="#_6-工具操作-定义结构体" aria-label="Permalink to &quot;6. 工具操作：定义结构体&quot;">​</a></h2><p data-src-line="62" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">IDA 和 Ghidra 都支持手动定义结构体，然后应用到变量上：</p><ul data-src-line="64" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md"><li data-src-line="64" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">在 IDA 里，<code>Shift+F1</code> 打开结构体窗口，定义结构体；对变量按 <code>T</code> 应用结构体类型。</li><li data-src-line="65" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">在 Ghidra 里，Data Type Manager 里定义结构体，右键变量设置类型。</li></ul><p data-src-line="67" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">定义结构体后，反编译产物会从 <code>*(int*)(ptr+4)</code> 变成 <code>ptr-&gt;field2</code>，可读性大幅提升。<strong>「边分析边定义类型」是逆向的核心工作流</strong>，和「边分析边重命名」一样重要。</p><hr><blockquote data-src-line="71" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md"><p data-src-line="71" data-src-file="reverse-engineering/05-static-analysis/chapter-02-type-recovery.md">本章建立的是类型恢复的方法：从偏移恢复结构体、从缩放恢复数组、从调用约定恢复参数，辅以控制流和数据流分析。这些是还原 C++ 类结构的基础。下一章讲 C++ 特有的两块——<a href="./chapter-03-vtable-rtti.html">虚函数表与 RTTI</a>。</p></blockquote>`,29)])])}const y=a(r,[["render",n]]);export{k as __pageData,y as default};
